    void zwp_text_input_manager_v3::handle_destroy(
        ::wl_client *client,
        struct wl_resource *resource)
    {
        Q_UNUSED(client);
        Resource *qtResource = Resource::fromResource(resource);
        if (Q_UNLIKELY(!qtResource->zwp_text_input_manager_v3_object)) {
            wl_resource_destroy(resource);
            return;
        }
        static_cast<zwp_text_input_manager_v3 *>(qtResource->zwp_text_input_manager_v3_object)->zwp_text_input_manager_v3_destroy(
            qtResource);
    }

    void zwp_text_input_manager_v3::handle_get_text_input(
        ::wl_client *client,
        struct wl_resource *resource,
        uint32_t id,
        struct ::wl_resource *seat)
    {
        Q_UNUSED(client);
        Resource *qtResource = Resource::fromResource(resource);
        if (Q_UNLIKELY(!qtResource->zwp_text_input_manager_v3_object)) {
            return;
        }
        static_cast<zwp_text_input_manager_v3 *>(qtResource->zwp_text_input_manager_v3_object)->zwp_text_input_manager_v3_get_text_input(
            qtResource,
            id,
            seat);
    }
